const icon=(name,small=false)=>`<svg class="icon${small?' icon-sm':''}" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||''}</svg>`;
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);el.removeAttribute('data-icon')})}
const state={data:null,folders:[],locale:localStorage.getItem('slovo_locale')||'ru',view:'home',folder:null,folderQuery:'',folderFilter:'all',study:null,revealed:false,review:null,submitting:false,audio:null,catalog:null,catalogCategory:'',catalogQuery:'',catalogSet:null,crop:null,game:null,gamePick:{term:null,translation:null},gameReview:null,gameLetters:null,gameWrong:null,gameStartedAt:0};
const content=document.querySelector('#content'),modal=document.querySelector('#modal'),modalContent=document.querySelector('#modalContent');
new MutationObserver(()=>{if(content.querySelector('.study-shell'))window.scrollTo({top:0,behavior:'instant'})}).observe(content,{childList:true});
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const t=(key,vars={})=>Object.entries(vars).reduce((s,[k,v])=>s.replace(`{${k}}`,v),I18N[state.locale]?.[key]||EN[key]||key);
const vibrate=type=>tg?.HapticFeedback?.notificationOccurred(type);
const pluralRu=(n,one,few,many)=>{const x=Math.abs(n)%100,y=x%10;return x>10&&x<20?many:y===1?one:y>=2&&y<=4?few:many};
const countWords=n=>state.locale==='ru'?`${n} ${pluralRu(n,'слово','слова','слов')}`:`${n} ${t('words').toLowerCase()}`;
const langName=code=>LANGUAGE_NAMES[state.locale]?.[code]||LANGUAGE_NAMES.en[code]||code;
const directionText=(from,to)=>state.locale==='ru'?`С ${RU_FROM[from]} на ${RU_TO[to]}`:`${langName(from)} → ${langName(to)}`;
const initials=name=>(name||'S').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const timezoneOffset=()=>new Date().getTimezoneOffset();
const startParam=()=>tg?.initDataUnsafe?.start_param||new URLSearchParams(location.search).get('tgWebAppStartParam')||'';
function appSessionId(){let id=sessionStorage.getItem('slovo_app_session');if(!id){id=crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;sessionStorage.setItem('slovo_app_session',id)}return id}
const requestId=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;

async function api(path,options={}){const form=options.body instanceof FormData;const headers={'X-Telegram-Init-Data':tg?.initData||'','X-Slovo-Start-Param':startParam(),...(form?{}:{'Content-Type':'application/json'}),...(options.headers||{})};const response=await fetch(path,{...options,headers});if(!response.ok){let detail=t('error');try{detail=(await response.json()).detail||detail}catch{}if(detail==='folder_word_limit')detail=t('folderWordLimit');if(I18N[state.locale]?.[detail])detail=t(detail);throw new Error(detail)}return response.json()}
function avatarMarkup(avatar,name,className='user-avatar'){return avatar?.url?`<span class="${className}"><img src="${esc(avatar.url)}" alt=""></span>`:`<span class="${className}">${initials(name)}</span>`}
function updateHeaderAvatar(){const u=state.data?.user,button=document.querySelector('#avatarButton');if(!u||!button)return;button.innerHTML=u.avatar?.url?`<img src="${esc(u.avatar.url)}" alt="">`:initials(u.name)}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,2300)}
function openModal(html){modalContent.innerHTML=html;modal.hidden=false;document.body.style.overflow='hidden'}
function closeModal(){modal.hidden=true;modalContent.innerHTML='';document.body.style.overflow=''}
function setActive(view){document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.action===view));window.scrollTo({top:0,left:0,behavior:'instant'})}
function showNav(show=true){document.querySelector('.bottom-nav').classList.toggle('hidden',!show);document.querySelector('.topbar').style.display=show?'flex':'none'}
function applyLocale(){document.documentElement.lang=state.locale;document.documentElement.dir=state.locale==='ar'?'rtl':'ltr';document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n))}
function languageOptions(selected,exclude=''){return Object.keys(LANGUAGE_NAMES.en).filter(c=>c!==exclude).map(c=>`<option value="${c}" ${c===selected?'selected':''}>${esc(langName(c))}</option>`).join('')}
function skeletons(){return `<div class="folder-grid"><div class="folder-card skeleton"></div><div class="folder-card skeleton"></div></div>`}
function renderLoading(){showNav(true);content.innerHTML=`<section class="hero"><p class="eyebrow">SLOVO</p><h1>${t('loading')}</h1><div class="loader"></div></section>${skeletons()}`}
function renderError(error){showNav(false);content.innerHTML=`<section class="launch-screen"><img src="/static/logo.png" class="launch-logo" alt="Slovo"><h1>${t('loadError')}</h1><p>${esc(error?.message||t('error'))}</p><button class="primary" data-action="retry">${t('retry')}</button></section>`}

async function loadCore(){renderLoading();const [bootstrap,home]=await Promise.all([api('/api/bootstrap'),api('/api/home')]);state.data=bootstrap;state.locale=bootstrap.locale||state.locale;localStorage.setItem('slovo_locale',state.locale);state.folders=home.folders;state.home=home;applyLocale();updateHeaderAvatar();api('/api/analytics/open',{method:'POST',body:JSON.stringify({session_id:appSessionId()})}).catch(()=>{})}
async function refreshHome(){const home=await api('/api/home');state.folders=home.folders;state.home=home}
function folderCard(f,action='folder'){return `<button class="folder-card" data-action="${action}" data-id="${f.id}"><span class="folder-icon">${icon(f.is_slovo_set?'book':'folder')}</span>${f.is_slovo_set?`<span class="set-badge">${t('slovoSet')}</span>`:''}<h3 title="${esc(f.name)}">${esc(f.name)}</h3><div class="pair">${esc(directionText(f.source_lang,f.target_lang))}</div><div class="meta"><span>${countWords(f.word_count)}</span><span>${f.due_count} ${t('due').toLowerCase()}</span></div><div class="mini-progress"><i style="width:${Math.min(100,Math.max(0,f.progress_percent||0))}%"></i></div></button>`}
function categoryButton(c,selected=false){return `<button class="category-button ${selected?'selected':''}" data-action="catalog-category" data-category="${esc(c.slug)}"><span>${icon(c.icon)}</span><b>${esc(c.title)}</b></button>`}
function setCard(s){return `<button class="set-card" data-action="catalog-set" data-slug="${esc(s.slug)}"><span class="set-art tone-${esc(s.category_slug)}">${icon(s.icon)}</span><span class="set-copy"><span class="set-title-line"><b>${esc(s.title)}</b>${s.added?`<em>${t('addedSet')}</em>`:''}</span><span class="set-description">${esc(s.description)}</span><small>${t('cardsMeta')}</small>${s.added?`<span class="set-progress"><i style="width:${s.progress_percent}%"></i></span><small>${t('progress')}: ${s.progress_percent}%</small>`:''}</span></button>`}
function renderHome(){state.view='home';showNav(true);setActive('home');const due=state.home?.due_count||0,mins=state.home?.estimated_minutes||0,categories=state.home?.catalog_categories||[],starters=state.home?.starter_sets||[];content.innerHTML=`<section class="hero"><p class="eyebrow">SLOVO</p><h1>${due?t('repeatTime'):t('hello')}</h1><p>${due?t('todayLine',{count:countWords(due),minutes:t('minutes',{n:mins})}):t('todayDone')}</p><div class="hero-actions">${due?`<button class="primary" data-action="learn">${icon('cards',true)}${t('start')}</button>`:''}<button class="secondary hero-play" data-action="play-hub">${icon('play',true)}${t('play')}</button></div></section><section class="play-promo"><span>${icon('play')}</span><div><h2>${t('playWords')}</h2><p>${t('playDescription')}</p></div><button class="primary" data-action="play-hub">${t('play')}</button></section><section class="catalog-preview"><div class="section-head compact"><div><h2>${t('slovoSets')}</h2><p>${t('setsSubtitle')}</p></div><button class="text-button" data-action="catalog">${t('seeAll')}</button></div><div class="category-strip">${categories.map(c=>categoryButton(c)).join('')}</div><div class="starter-list">${starters.map(setCard).join('')}</div></section><div class="section-head"><h2>${t('myFolders')}</h2><button class="icon-button" data-action="new-folder" aria-label="${t('newFolder')}">${icon('plus')}</button></div>${state.folders.length?`<div class="folder-grid">${state.folders.map(f=>folderCard(f)).join('')}</div>`:`<div class="empty home-empty"><div class="empty-mark">${icon('folder')}</div><p>${t('emptyFolders')}</p><div class="button-row"><button class="primary" data-action="new-folder">${icon('plus',true)}${t('newFolder')}</button><button class="secondary" data-action="catalog">${icon('book',true)}${t('startWithSet')}</button></div></div>`}`}
async function renderCatalog(category=state.catalogCategory){state.view='catalog';showNav(true);setActive('home');state.catalogCategory=category||'';content.innerHTML=`<button class="back-link" data-action="home">${icon('back',true)}${t('folders')}</button><div class="section-head"><div><h1>${t('slovoSets')}</h1><p class="muted">${t('setsSubtitle')}</p></div></div>${skeletons()}`;const params=new URLSearchParams({category:state.catalogCategory,q:state.catalogQuery});state.catalog=await api(`/api/catalog?${params}`);drawCatalog()}
function drawCatalog(){const data=state.catalog;content.innerHTML=`<button class="back-link" data-action="home">${icon('back',true)}${t('folders')}</button><div class="section-head"><div><h1>${t('slovoSets')}</h1><p class="muted">${t('setsSubtitle')}</p></div></div><div class="toolbar"><input class="search" id="catalogSearch" value="${esc(state.catalogQuery)}" placeholder="${t('catalogSearch')}"><button class="icon-button" data-action="catalog-search" aria-label="${t('search')}">${icon('search')}</button></div><div class="filter-row catalog-filters"><button class="chip ${state.catalogCategory?'':'selected'}" data-action="catalog-category" data-category="">${t('filterAll')}</button>${data.categories.map(c=>`<button class="chip ${state.catalogCategory===c.slug?'selected':''}" data-action="catalog-category" data-category="${esc(c.slug)}">${icon(c.icon,true)}${esc(c.title)}</button>`).join('')}</div><div class="set-list">${data.sets.length?data.sets.map(setCard).join(''):`<div class="empty"><div class="empty-mark">${icon('search')}</div><p>${t('noSets')}</p><button class="secondary" data-action="catalog-clear">${t('filterAll')}</button></div>`}</div>`}
async function renderCatalogSet(slug){state.view='catalog-set';showNav(true);setActive('home');content.innerHTML=`<button class="back-link" data-action="catalog">${icon('back',true)}${t('slovoSets')}</button><section class="folder-header skeleton" style="height:240px"></section>${skeletons()}`;state.catalogSet=await api(`/api/catalog/${encodeURIComponent(slug)}`);drawCatalogSet()}
function drawCatalogSet(){const s=state.catalogSet;content.innerHTML=`<button class="back-link" data-action="catalog">${icon('back',true)}${t('slovoSets')}</button><section class="set-hero"><span class="set-art large tone-${esc(s.category_slug)}">${icon(s.icon)}</span><div><p class="eyebrow">${t('slovoSet')}</p><h1>${esc(s.title)}</h1><p>${esc(s.description)}</p><div class="set-facts"><span>${icon(s.category_icon,true)}${esc(s.category_title)}</span><span>${t('cardsMeta')}</span></div></div></section><div class="stack set-actions">${s.added?`<button class="primary" data-action="study-setup" data-id="${s.folder_id}">${icon('cards',true)}${s.progress_percent?t('continueStudy'):t('study')}</button><button class="secondary" data-action="games" data-id="${s.folder_id}">${icon('play',true)}${t('play')}</button><button class="danger" data-action="detach-set" data-slug="${esc(s.slug)}">${t('detachSet')}</button>`:`<button class="primary" data-action="attach-set" data-slug="${esc(s.slug)}">${icon('plus',true)}${t('addAndLearn')}</button><button class="secondary" data-action="play-catalog" data-slug="${esc(s.slug)}">${icon('play',true)}${t('play')}</button>`}<button class="secondary" data-action="copy-set" data-slug="${esc(s.slug)}">${icon('copy',true)}${t('copySet')}</button></div><div class="section-head"><h2>${t('wordList')}</h2><span class="set-badge">${s.cards.length}</span></div><div class="card-list">${s.cards.map(c=>wordRow(c,false,'en')).join('')}</div>`}
function learningModeCards(active='learn'){return `<div class="learning-modes"><button class="learning-mode ${active==='learn'?'selected':''}" data-action="learn"><span>${icon('cards')}</span><b>${t('learnWordsMode')}</b><small>${t('learnWordsHint')}</small></button><button class="learning-mode ${active==='play'?'selected':''}" data-action="play-hub"><span>${icon('play')}</span><b>${t('playWords')}</b><small>${t('gamesModeHint')}</small></button></div>`}
function renderLearn(){state.view='learn';showNav(true);setActive('learn');content.innerHTML=`<div class="section-head"><div><h1>${t('learn')}</h1><p class="muted">${t('playDescription')}</p></div></div>${learningModeCards('learn')}<div class="section-head"><h2>${t('chooseFolder')}</h2></div>${state.folders.length?`<div class="folder-grid">${state.folders.map(f=>folderCard(f,'study-setup')).join('')}</div>`:`<div class="empty"><p>${t('emptyFolders')}</p></div>`}`}
function playSetCard(s){const action=s.added?'games':'play-catalog',identity=s.added?`data-id="${s.folder_id}"`:`data-slug="${esc(s.slug)}"`;return `<button class="set-card" data-action="${action}" ${identity}><span class="set-art tone-${esc(s.category_slug)}">${icon(s.icon)}</span><span class="set-copy"><span class="set-title-line"><b>${esc(s.title)}</b>${s.added?`<em>${t('addedSet')}</em>`:''}</span><span class="set-description">${esc(s.description)}</span><small>${t('cardsMeta')}</small></span></button>`}
async function renderPlayHub(){state.view='play-hub';showNav(true);setActive('learn');content.innerHTML=`<div class="section-head"><div><h1>${t('playWords')}</h1><p class="muted">${t('playDescription')}</p></div></div>${learningModeCards('play')}${skeletons()}`;const catalog=await api('/api/catalog?');const personal=state.folders.filter(f=>!f.is_slovo_set);content.innerHTML=`<div class="section-head"><div><h1>${t('playWords')}</h1><p class="muted">${t('choosePlayFolder')}</p></div></div>${learningModeCards('play')}<div class="section-head"><h2>${t('personalGameFolders')}</h2></div>${personal.length?`<div class="folder-grid">${personal.map(f=>folderCard(f,'games')).join('')}</div>`:`<div class="empty"><p>${t('emptyFolders')}</p></div>`}<div class="section-head"><h2>${t('slovoGameSets')}</h2></div><div class="set-list">${catalog.sets.map(playSetCard).join('')}</div>`}

async function renderFolder(id,{append=false}={}){state.view='folder';showNav(true);setActive('home');if(!append)content.innerHTML=`<button class="back-link" data-action="home">${icon('back',true)}${t('folders')}</button><section class="folder-header skeleton" style="height:190px"></section>${skeletons()}`;const offset=append?(state.folder?.cards.length||0):0;const params=new URLSearchParams({offset,limit:50,q:state.folderQuery,filter:state.folderFilter});const f=await api(`/api/folders/${id}?${params}`);if(append&&state.folder){state.folder.cards.push(...f.cards);state.folder.has_more=f.has_more}else state.folder=f;drawFolder();if(!append)api(`/api/folders/${id}/enrich`,{method:'POST'}).catch(()=>{})}
function actionCard(action,id,iconName,title,subtitle){return `<button class="action-card" data-action="${action}" ${id?`data-id="${id}"`:''}><span class="action-icon">${icon(iconName)}</span><span class="action-copy"><b>${title}</b><span>${subtitle}</span></span></button>`}
function drawFolder(){const f=state.folder,canEdit=['owner','editor'].includes(f.role),owner=f.role==='owner';content.innerHTML=`<button class="back-link" data-action="home">${icon('back',true)}${t('folders')}</button><section class="folder-header">${f.is_slovo_set?`<span class="set-badge">${t('slovoSet')}</span>`:`<p class="eyebrow">${t('folder')}</p>`}<h1 title="${esc(f.name)}">${esc(f.name)}</h1><div class="pair">${esc(directionText(f.source_lang,f.target_lang))}</div><div class="stats"><div class="stat"><strong>${f.word_count}</strong><span>${t('words')}</span></div><div class="stat"><strong>${f.due_count}</strong><span>${t('due')}</span></div></div><div class="mini-progress"><i style="width:${Math.min(100,Math.max(0,f.progress_percent||0))}%"></i></div><p class="hint">${t('progress')}: ${f.progress_percent}%</p></section><div class="action-grid">${actionCard('study-setup',f.id,'cards',t('study'),`${t('due')}: ${f.due_count}`)}${actionCard('games',f.id,'play',t('play'),t('games'))}${canEdit?actionCard('add-words',null,'plus',t('addWords'),esc(directionText(f.source_lang,f.target_lang))):''}${owner?actionCard('invite',null,'share',t('shareFolder'),t('member'))+actionCard('folder-settings',null,'settings',t('settings'),t('participants')):''}${f.is_slovo_set?actionCard('catalog-set',null,'book',t('slovoSet'),t('seeAll')).replace('<button','<button data-slug="'+esc(f.set_slug)+'"'):''}</div><div class="section-head"><h2>${t('wordList')}</h2></div><div class="toolbar"><input class="search" id="folderSearch" value="${esc(state.folderQuery)}" placeholder="${t('search')}"><button class="icon-button" data-action="run-search" aria-label="${t('search')}">${icon('search')}</button></div><div class="filter-row">${[['all','filterAll'],['due','review'],['errors','errorsOnly']].map(([v,k])=>`<button class="chip ${state.folderFilter===v?'selected':''}" data-action="filter-cards" data-filter="${v}">${t(k)}</button>`).join('')}</div><div class="card-list" style="margin-top:12px">${f.cards.length?f.cards.map(c=>wordRow(c,canEdit,f.source_lang)).join(''):`<div class="empty"><p>${t('noWords')}</p></div>`}</div>${f.has_more?`<button class="secondary" style="width:100%;margin-top:12px" data-action="load-more">${t('loadMore')}</button>`:''}`}
function wordRow(c,canEdit,lang){return `<div class="word-row" data-card-id="${c.id}"><div class="word-copy"><b>${esc(c.term)}</b>${c.transcription?`<div class="transcription">${esc(c.transcription)}</div>`:''}<span>${esc(c.translation)}</span></div><button class="sound-button" data-action="speak-card" data-id="${c.id}" data-text="${esc(c.term)}" data-lang="${lang}" data-audio="${esc(c.audio_url||'')}" aria-label="${t('listen')}">${icon('volume')}</button>${canEdit?`<button class="more-button" data-action="edit-card" data-id="${c.id}" aria-label="${t('edit')}">${icon('more')}</button>`:''}</div>`}

function newFolderModal(){const rid=requestId();openModal(`<h2>${t('newFolder')}</h2><form id="folderForm"><div class="field"><label>${t('name')}</label><textarea name="name" maxlength="160" required autofocus></textarea></div><div class="field"><label>${t('source')}</label><select name="source">${languageOptions('en')}</select></div><div class="field"><label>${t('target')}</label><select name="target">${languageOptions('ru')}</select></div><div class="button-row"><button type="button" class="secondary" data-action="close-modal">${t('cancel')}</button><button class="primary">${t('create')}</button></div></form>`);document.querySelector('#folderForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target),button=e.submitter;button.disabled=true;try{const f=await api('/api/folders',{method:'POST',body:JSON.stringify({name:fd.get('name'),source_lang:fd.get('source'),target_lang:fd.get('target'),request_id:rid})});closeModal();await refreshHome();vibrate('success');renderFolder(f.id)}catch(err){toast(err.message);button.disabled=false}})}
function addWordsModal(){const rid=requestId();openModal(`<h2>${t('addWords')}</h2><form id="wordsForm"><div class="field"><textarea name="words" required placeholder="apple — яблоко\nbook — книга"></textarea><div class="hint">${t('addHint')}</div></div><div class="button-row"><button type="button" class="secondary" data-action="close-modal">${t('cancel')}</button><button class="primary">${t('save')}</button></div></form>`);document.querySelector('#wordsForm').addEventListener('submit',async e=>{e.preventDefault();const raw=new FormData(e.target).get('words');const items=raw.split(/\n/).map(x=>x.trim()).filter(Boolean).map(line=>{const p=line.includes('\t')?line.split(/\t/,2):line.split(/\s+[—–-]\s+/,2);return{term:(p[0]||'').trim(),translation:(p[1]||'').trim()}}).filter(x=>x.term&&x.translation);if(!items.length)return toast(t('addHint'));e.submitter.disabled=true;try{const result=await api(`/api/folders/${state.folder.id}/cards`,{method:'POST',body:JSON.stringify({items,skip_duplicates:true,request_id:rid})});closeModal();toast(`${t('added')}: ${result.added}${result.duplicates?` · ${t('duplicates')}: ${result.duplicates}`:''}`);await refreshHome();renderFolder(state.folder.id)}catch(err){toast(err.message);e.submitter.disabled=false}})}

async function studySetup(id){const f=state.folders.find(x=>x.id===Number(id))||state.folder;if(!f)return;api(`/api/folders/${f.id}/enrich`,{method:'POST'}).catch(()=>{});let unfinished=null;try{unfinished=await api(`/api/study/unfinished?folder_id=${f.id}`)}catch{}openModal(`${unfinished?.id?`<div class="invite-result"><b>${t('resume')}</b><div class="button-row" style="margin-top:10px"><button class="primary" data-action="resume-study" data-session="${unfinished.id}">${t('resume')}</button><button class="secondary" data-action="dismiss-resume">${t('newSession')}</button></div></div>`:''}<div id="newStudyBlock"><h2>${t('study')}</h2><p class="muted">${t('randomRound')}</p><form id="studyForm"><h3>${t('direction')}</h3>${[['fwd',f.source_lang,f.target_lang],['rev',f.target_lang,f.source_lang]].map(([v,a,b],i)=>`<label class="choice"><input type="radio" name="direction" value="${v}" ${i?'':'checked'}><div><b>${esc(directionText(a,b))}</b></div></label>`).join('')}<div class="button-row"><button type="button" class="secondary" data-action="close-modal">${t('cancel')}</button><button class="primary">${t('start')}</button></div></form></div>`);if(unfinished?.id)document.querySelector('#newStudyBlock').hidden=true;document.querySelector('#studyForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);e.submitter.disabled=true;try{state.study=await api('/api/study',{method:'POST',body:JSON.stringify({folder_id:f.id,direction:fd.get('direction'),mode:'due',study_format:'cards',timezone_offset:timezoneOffset()})});closeModal();state.revealed=false;state.review=null;renderStudy()}catch(err){toast(err.message);e.submitter.disabled=false}})}
function studyAudioButton(s){return s.front_lang?`<button class="sound-button" data-action="speak-study" data-audio="${esc(s.audio_url||'')}" aria-label="${t('listen')}">${icon('volume')}</button>`:''}
function wordLengthClass(value){const length=Array.from(String(value||'')).length;return length>16?'word-very-long':length>10?'word-long':''}
function learningDetails(s){const audio=s.detail_term?`<button class="sound-button" data-action="speak-card" data-id="${s.card_id}" data-text="${esc(s.detail_term)}" data-lang="${esc(s.detail_lang||'en')}" data-audio="${esc(s.detail_audio_url||'')}" aria-label="${t('listen')}">${icon('volume')}</button>`:'';if(!s.details_transcription&&!audio)return'';return `<details class="learning-details"><summary>${icon('volume',true)}${t('pronunciationDetails')}</summary><div class="learning-details-body"><div class="learning-detail-row"><span>${s.details_transcription?t('transcription'):t('listen')}</span>${s.details_transcription?`<b>${esc(s.details_transcription)}</b>`:''}${audio}</div></div></details>`}
function renderStudy(){const entering=state.view!=='study';stopAudio();state.view='study';showNav(false);if(entering)window.scrollTo({top:0,left:0,behavior:'instant'});const s=state.study;if(s.done)return renderStudyDone();const pct=s.total?Math.min(100,Math.round(((s.position||1)-1)/s.total*100)):0;const front=`<div class="study-face"><h1 class="study-word ${wordLengthClass(s.front)}">${esc(s.front)}</h1>${s.transcription?`<div class="transcription">${esc(s.transcription)}</div>`:''}${studyAudioButton(s)}</div>`;const body=`${front}${state.revealed?`<div class="study-answer"><div class="study-back">${esc(s.back)}</div>${learningDetails(s)}<div class="button-row study-actions"><button class="danger" data-action="commit-answer" data-success="false">${t('dontKnow')}</button><button class="primary" data-action="commit-answer" data-success="true">${t('know')}</button></div></div>`:`<div class="study-actions"><button class="primary" style="width:100%" data-action="reveal">${t('showAnswer')}</button></div>`}`;content.innerHTML=`<div class="study-shell"><div class="study-top"><button class="secondary study-exit" data-action="exit-study" aria-label="${t('exit')}">${icon('close')}</button><div class="study-count">${Math.min(s.position||1,s.total)} ${state.locale==='ru'?'из':'/'} ${s.total}</div><div class="progress"><i style="width:${pct}%"></i></div></div><section class="study-card ${state.revealed?'revealed':''}">${body}</section></div>`}
function renderStudyDone(){const s=state.study;content.innerHTML=`<section class="study-card"><div class="result-mark">${icon('check')}</div><h1>${s.total?t('done'):t('nothingDue')}</h1>${s.total?`<div class="result-stats simple-results"><div class="stat"><strong>${s.known??s.first_correct??0} ${state.locale==='ru'?'из':'/'} ${s.total}</strong><span>${t('knownResult')}</span></div><div class="stat"><strong>${s.unknown??s.errors??0}</strong><span>${t('unknownResult')}</span></div></div>`:''}<div class="stack">${s.errors?`<button class="primary" data-action="repeat-errors">${t('repeatUnknown')}</button>`:''}<button class="secondary" data-action="study-setup" data-id="${s.folder_id}">${t('moreWords')}</button><button class="secondary" data-action="return-folder" data-id="${s.folder_id}">${t('backFolders')}</button></div></section>`;refreshHome()}
function exitStudyModal(){openModal(`<h2>${t('leaveStudy')}</h2><p class="muted">${t('leaveStudyHint')}</p><div class="stack"><button class="primary" data-action="pause-study">${t('pauseStudy')}</button><button class="danger" data-action="finish-study">${t('finishStudy')}</button><button class="secondary" data-action="close-modal">${t('cancel')}</button></div>`)}
async function commitAnswer(success,answerText=null){if(state.submitting)return;state.submitting=true;document.querySelectorAll('[data-action="commit-answer"]').forEach(x=>x.disabled=true);try{state.study=await api(`/api/study/${state.study.id}/answer`,{method:'POST',body:JSON.stringify({success,card_id:state.study.card_id,answer_text:answerText??state.review?.answer??null})});state.revealed=false;state.review=null;vibrate(success?'success':'warning');setTimeout(renderStudy,220)}catch(err){toast(err.message);state.submitting=false;renderStudy();return}state.submitting=false}

const gameEventId=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const gameTitle=type=>t(type==='match'?'matchGame':type==='listen'?'listenGame':'buildGame');
async function renderGames(id){stopAudio();state.view='games';showNav(false);window.scrollTo({top:0,left:0,behavior:'instant'});const folder=state.folders.find(x=>x.id===Number(id))||state.folder||state.catalogSet;state.folder=folder;content.innerHTML=`<div class="game-shell"><div class="game-top"><button class="secondary game-exit" data-action="return-folder" data-id="${id}">${icon('back')}</button><div><p class="eyebrow">${t('games')}</p><h1>${esc(folder?.name||'')}</h1></div></div>${skeletons()}</div>`;const [options,unfinished]=await Promise.all([api(`/api/games/options?folder_id=${id}`),api(`/api/games/unfinished?folder_id=${id}`)]);state.gameOptions=options;content.innerHTML=`<div class="game-shell"><div class="game-top"><button class="secondary game-exit" data-action="return-folder" data-id="${id}">${icon('back')}</button><div><p class="eyebrow">${t('games')}</p><h1>${esc(options.folder_name)}</h1></div></div>${unfinished.id?`<button class="resume-game" data-action="resume-game" data-round="${unfinished.id}"><span>${icon('play')}</span><span><b>${t('resumeGame')}</b><small>${gameTitle(unfinished.game_type)} · ${unfinished.game_type==='match'?t('collected',{done:unfinished.collected,total:unfinished.total}):t('completedCount',{done:unfinished.completed,total:unfinished.total})}</small></span></button>`:''}<div class="section-head"><h2>${t('chooseGame')}</h2></div><div class="game-picker">${gameChoice('match','activity')}${gameChoice('listen','volume')}${gameChoice('build','cards')}</div></div>`}
function gameChoice(type,iconName){const o=state.gameOptions.games[type];return `<button class="game-choice ${o.available?'':'disabled'}" data-action="start-game" data-type="${type}" ${o.available?'':'disabled'}><span class="game-choice-icon">${icon(iconName)}</span><span><b>${gameTitle(type)}</b><small>${t(type==='match'?'matchHint':type==='listen'?'listenHint':'buildHint')}</small><em>${o.available?t('roundSize',{n:o.size}):t(o.reason)}</em></span></button>`}
async function startGame(type){if(state.submitting)return;state.submitting=true;document.querySelectorAll('[data-action="start-game"]').forEach(x=>x.disabled=true);try{state.game=await api('/api/games',{method:'POST',body:JSON.stringify({folder_id:state.folder.id,game_type:type})});resetGameUi();renderGame()}finally{state.submitting=false}}
function resetGameUi(){state.gamePick={term:null,translation:null};state.gameReview=null;state.gameLetters=null;state.gameWrong=null;state.gameStartedAt=Date.now()}
function renderGame(){stopAudio();state.view='game';showNav(false);if(state.game.done)return renderGameDone();if(state.game.game_type==='match')renderMatchGame();else if(state.game.game_type==='listen')renderListenGame();else renderBuildGame()}
function gameHeader(label,progress,pct){return `<div class="game-top"><button class="secondary game-exit" data-action="exit-game" aria-label="${t('exit')}">${icon('close')}</button><div class="game-heading"><small>${esc(state.game.folder_name)}</small><b>${label}</b></div><div class="game-progress-copy">${progress}</div><div class="progress"><i style="width:${pct}%"></i></div></div>`}
function renderMatchGame(){const g=state.game,pct=g.total?g.collected/g.total*100:0,matched=new Set(g.matched_ids||[]);content.innerHTML=`<div class="game-shell">${gameHeader(t('matchGame'),t('collected',{done:g.collected,total:g.total}),pct)}<div class="match-board"><div class="match-column">${g.terms.map(x=>matchTile('term',x,matched)).join('')}</div><div class="match-column">${g.translations.map(x=>matchTile('translation',x,matched)).join('')}</div></div><p class="game-note">${t('wrongConnections')}: ${g.result.wrong_connections}</p></div>`}
function matchTile(side,item,matched){const selected=state.gamePick[side]===item.card_id,wrong=state.gameWrong?.[side]===item.card_id,isMatched=matched.has(item.card_id);return `<button class="match-tile ${selected?'selected':''} ${wrong?'wrong':''} ${isMatched?'matched':''}" data-action="match-tile" data-side="${side}" data-id="${item.card_id}" ${isMatched?'disabled':''} aria-label="${esc(item.text)}${wrong?` · ${t('wrong')}`:isMatched?` · ${t('correct')}`:''}">${esc(item.text)}<span aria-hidden="true">${wrong?icon('close',true):isMatched?icon('check',true):''}</span></button>`}
async function chooseMatch(side,id){if(state.submitting)return;if(state.gamePick[side]===id)state.gamePick[side]=null;else state.gamePick[side]=id;renderMatchGame();if(!state.gamePick.term||!state.gamePick.translation)return;state.submitting=true;const term=state.gamePick.term,translation=state.gamePick.translation;try{const result=await api(`/api/games/${state.game.id}/action`,{method:'POST',body:JSON.stringify({event_id:gameEventId(),action:'match',card_id:term,translation_card_id:translation})});state.game=result;if(result.outcome==='wrong'){state.gameWrong={term,translation};vibrate('error');renderMatchGame();setTimeout(()=>{state.gamePick={term:null,translation:null};state.gameWrong=null;renderGame()},500)}else{state.gamePick={term:null,translation:null};vibrate('success');renderGame()}}finally{state.submitting=false}}
function renderListenGame(){const g=state.game;if(state.gameReview)return renderListenReview();const q=g.question,pct=g.total?g.completed/g.total*100:0;content.innerHTML=`<div class="game-shell">${gameHeader(t('listenGame'),t('completedCount',{done:g.completed,total:g.total}),pct)}<section class="listen-card"><p>${t('listenPrompt')}</p><button class="listen-speaker" data-action="game-audio" aria-label="${t('listen')}">${icon('volume')}</button>${state.audioError?`<p class="error-copy">${t('audioUnavailable')}</p><button class="secondary" data-action="game-audio">${t('retryAudio')}</button>`:''}<div class="listen-options">${q.choices.map(x=>`<button data-action="listen-answer" data-id="${x.card_id}">${esc(x.translation)}</button>`).join('')}</div><button class="secondary" data-action="game-unknown">${t('unknown')}</button>${state.audioError?`<button class="text-button" data-action="game-skip">${t('technicalSkip')}</button>`:''}</section></div>`}
function renderListenReview(){const r=state.gameReview.reveal,q=state.gameReview.question;content.innerHTML=`<div class="game-shell">${gameHeader(t('listenGame'),t('completedCount',{done:state.game.completed,total:state.game.total}),state.game.total?state.game.completed/state.game.total*100:0)}<section class="listen-card review"><div class="result-mark ${r.outcome==='correct'?'':'warn'}">${r.outcome==='correct'?icon('check'):icon('close')}</div><h1>${esc(r.term)}</h1>${r.transcription?`<div class="transcription">${esc(r.transcription)}</div>`:''}<h2>${esc(r.translation)}</h2><div class="listen-options answered">${q.choices.map(x=>{const correct=x.card_id===q.card_id,wrong=x.card_id===r.selected_id&&!correct;return `<button class="${correct?'correct':''} ${wrong?'wrong':''}" disabled>${correct?icon('check',true):wrong?icon('close',true):''}${esc(x.translation)}</button>`}).join('')}</div><button class="sound-button review-audio" data-action="game-review-audio" data-text="${esc(r.term)}" data-lang="${esc(q.source_lang)}" data-id="${q.card_id}" data-audio="${esc(q.audio_url||'')}">${icon('volume')}</button><button class="primary" data-action="game-next">${t('next')}</button></section></div>`}
async function listeningAnswer(action,choiceId=null){if(state.submitting)return;state.submitting=true;const question=state.game.question;try{const result=await api(`/api/games/${state.game.id}/action`,{method:'POST',body:JSON.stringify({event_id:gameEventId(),action,card_id:question.card_id,choice_id:choiceId})});state.game=result;state.gameReview={question,reveal:result.reveal};vibrate(result.outcome==='correct'?'success':'warning');renderGame()}finally{state.submitting=false}}
function playListeningAudio(button){if(state.submitting)return;state.audioError=false;const q=state.game.question;speak(q.speech_text,q.source_lang,q.card_id,button,q.audio_url||'')}
function ensureLetters(){const q=state.game.question;if(state.gameLetters?.cardId===q.card_id)return;const tiles=[...q.term].map((char,id)=>({id,char}));for(let i=tiles.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[tiles[i],tiles[j]]=[tiles[j],tiles[i]]}if(tiles.length>1&&tiles.map(x=>x.char).join('').toLowerCase()===q.term.toLowerCase())[tiles[0],tiles[1]]=[tiles[1],tiles[0]];state.gameLetters={cardId:q.card_id,tiles,selected:[],fixed:0}}
function renderBuildGame(){if(state.gameReview)return renderBuildReview();ensureLetters();const g=state.game,q=g.question,l=state.gameLetters,pct=g.total?g.completed/g.total*100:0,selected=new Set(l.selected);content.innerHTML=`<div class="game-shell">${gameHeader(t('buildGame'),t('completedCount',{done:g.completed,total:g.total}),pct)}<section class="build-card"><p>${esc(q.translation)}</p><div class="built-word">${l.selected.length?l.selected.map((id,i)=>{const tile=l.tiles.find(x=>x.id===id);return `<button data-action="remove-letter" data-id="${id}" class="${i<l.fixed?'fixed':''}" ${i<l.fixed?'disabled':''}>${esc(tile.char)}</button>`}).join(''):`<span>${t('buildHint')}</span>`}</div><div class="letter-pool">${l.tiles.map(x=>`<button data-action="add-letter" data-id="${x.id}" ${selected.has(x.id)?'disabled':''}>${esc(x.char)}</button>`).join('')}</div><div class="button-row"><button class="secondary" data-action="clear-letters">${t('clear')}</button><button class="secondary" data-action="game-hint">${t('hint')}</button></div><button class="primary" data-action="check-word" ${l.selected.length===q.term.length?'':'disabled'}>${t('check')}</button><button class="text-button" data-action="game-unknown">${t('unknown')}</button></section></div>`}
function renderBuildReview(){const r=state.gameReview.reveal;content.innerHTML=`<div class="game-shell">${gameHeader(t('buildGame'),t('completedCount',{done:state.game.completed,total:state.game.total}),state.game.total?state.game.completed/state.game.total*100:0)}<section class="build-card review"><div class="result-mark">${icon('check')}</div><h1>${esc(r.term)}</h1><p>${r.outcome==='first'?t('firstTry'):r.outcome==='unknown'?t('unknown'):t('withHelp')}</p><button class="sound-button review-audio" data-action="game-review-audio" data-text="${esc(r.term)}" data-lang="en">${icon('volume')}</button><button class="primary" data-action="game-next">${t('next')}</button></section></div>`}
async function buildAction(action,assembled=null){if(state.submitting)return;state.submitting=true;const q=state.game.question;try{const result=await api(`/api/games/${state.game.id}/action`,{method:'POST',body:JSON.stringify({event_id:gameEventId(),action,card_id:q.card_id,assembled})});state.game=result;if(action==='hint'){const l=state.gameLetters;l.selected=[];for(let i=0;i<Math.min(q.term.length,l.fixed+1);i++)l.selected.push(i);l.fixed=l.selected.length;renderBuildGame()}else if(result.outcome==='wrong'){vibrate('error');toast(t('wrong'));renderBuildGame()}else{state.gameReview={reveal:result.reveal};vibrate(result.outcome==='first'?'success':'warning');renderGame()}}finally{state.submitting=false}}
function renderGameDone(){stopAudio();const g=state.game,r=g.result;showNav(false);let stats='';if(g.game_type==='match')stats=`${resultStat(r.matched,t('matchGame'))}${resultStat(r.wrong_connections,t('wrongConnections'))}`;else if(g.game_type==='listen')stats=`${resultStat(r.correct,t('correct'))}${resultStat(r.wrong,t('wrong'))}${resultStat(r.unknown,t('unknown'))}${resultStat(r.skipped,t('skipped'))}${resultStat(r.accuracy===null?t('noData'):`${r.accuracy}%`,t('accuracy'))}`;else stats=`${resultStat(r.first,t('firstTry'))}${resultStat(r.helped,t('withHelp'))}${resultStat(r.unknown,t('unknown'))}`;content.innerHTML=`<div class="game-shell"><section class="game-result"><div class="result-mark">${icon('check')}</div><p class="eyebrow">${gameTitle(g.game_type)}</p><h1>${t('done')}</h1><div class="result-stats">${stats}${resultStat(formatDuration(g.duration_seconds),t('duration'))}</div><div class="stack"><button class="primary" data-action="repeat-game">${t('playAgain')}</button>${r.mistakes?`<button class="secondary" data-action="repeat-game-errors">${t('repeatGameErrors')}</button>`:''}<button class="secondary" data-action="return-folder" data-id="${g.folder_id}">${t('toFolder')}</button></div></section></div>`}
function resultStat(value,label){return `<div class="stat"><strong>${value}</strong><span>${label}</span></div>`}
function exitGameModal(){openModal(`<h2>${t('leaveGame')}</h2><p class="muted">${t('leaveGameHint')}</p><div class="stack"><button class="primary" data-action="pause-game">${t('pauseGame')}</button><button class="danger" data-action="finish-game">${t('finishGame')}</button><button class="secondary" data-action="close-modal">${t('cancel')}</button></div>`)}

function stopAudio(){if(state.audio){try{state.audio.pause();state.audio.currentTime=0}catch{}state.audio=null}window.speechSynthesis?.cancel();document.querySelectorAll('.sound-button').forEach(x=>x.classList.remove('loading','is-playing'))}
async function speak(text,lang,cardId=null,button=null,audioUrl=''){
  if(button?.classList.contains('is-playing')){stopAudio();return}
  stopAudio();button?.classList.add('loading');
  const finish=()=>button?.classList.remove('loading','is-playing');
  // play() is intentionally called before any await so Telegram/iOS keeps the user gesture.
  if(audioUrl){
    const audio=new Audio(audioUrl);state.audio=audio;audio.preload='auto';
    audio.onplaying=()=>{button?.classList.remove('loading');button?.classList.add('is-playing')};
    audio.onended=finish;audio.onerror=()=>{finish();fallbackSpeech(text,lang,button)};
    audio.play().catch(()=>{finish();fallbackSpeech(text,lang,button)});
  }else fallbackSpeech(text,lang,button);
  if(!cardId)return;
  try{
    const info=await api(`/api/cards/${cardId}/pronunciation`,{method:'POST'});
    const card=state.folder?.cards?.find(c=>c.id===cardId);
    if(card){card.transcription=info.transcription||card.transcription;card.audio_url=info.audio_url||card.audio_url}
    if(state.study?.card_id===cardId){state.study.transcription=info.transcription||state.study.transcription;state.study.audio_url=info.audio_url||state.study.audio_url}
    if(state.game?.question?.card_id===cardId){state.game.question.audio_url=info.audio_url||state.game.question.audio_url}
  }catch{/* speech already started; metadata can be retried on the next tap */}
}
function fallbackSpeech(text,lang,button){
  if(!('speechSynthesis' in window)){button?.classList.remove('loading');return toast(t('error'))}
  const utter=new SpeechSynthesisUtterance(text);utter.lang=SPEECH_LANG[lang]||lang;utter.rate=.92;
  utter.onstart=()=>{button?.classList.remove('loading');button?.classList.add('is-playing')};
  utter.onend=()=>button?.classList.remove('loading','is-playing');
  utter.onerror=()=>{button?.classList.remove('loading','is-playing');toast(t('error'))};
  window.speechSynthesis.cancel();window.speechSynthesis.speak(utter);
}

function editCardModal(id){const c=state.folder.cards.find(x=>x.id===Number(id));if(!c)return;openModal(`<h2>${t('edit')}</h2><form id="cardForm"><div class="field"><label>${t('wordLabel')}</label><input name="term" value="${esc(c.term)}" required maxlength="250"></div><div class="field"><label>${t('translationLabel')}</label><input name="translation" value="${esc(c.translation)}" required maxlength="500"></div><div class="field"><label>${t('transcription')} · ${t('optional')}</label><input name="transcription" value="${esc(c.transcription||'')}" maxlength="250"></div><button class="primary" style="width:100%">${icon('check',true)}${t('save')}</button></form><div class="settings-section"><button class="danger" style="width:100%" data-action="delete-card" data-id="${id}">${icon('trash',true)}${t('delete')}</button></div>`);document.querySelector('#cardForm').addEventListener('submit',async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target));e.submitter.disabled=true;try{const result=await api(`/api/cards/${id}`,{method:'PATCH',body:JSON.stringify(fd)});Object.assign(c,result.card);closeModal();drawFolder();toast(t('saved'))}catch(err){toast(err.message);e.submitter.disabled=false}})}

function inviteModal(){openModal(`<h2>${t('shareFolder')}</h2><form id="inviteForm"><label class="choice"><input type="radio" name="role" value="member" checked><div><b>${t('member')}</b><span>${t('memberHint')}</span></div></label><label class="choice"><input type="radio" name="role" value="editor"><div><b>${t('editor')}</b><span>${t('editorHint')}</span></div></label><div class="button-row"><button type="button" class="secondary" data-action="close-modal">${t('cancel')}</button><button class="primary">${t('createInvite')}</button></div></form>`);document.querySelector('#inviteForm').addEventListener('submit',async e=>{e.preventDefault();const role=new FormData(e.target).get('role');e.submitter.disabled=true;try{const x=await api(`/api/folders/${state.folder.id}/invites`,{method:'POST',body:JSON.stringify({role})});modalContent.innerHTML=`<h2>${t('shareFolder')}</h2><div class="invite-result"><b>${t(role)}</b><div class="field"><input id="inviteUrl" value="${esc(x.url)}" readonly></div><div class="stack"><button class="primary" data-action="copy-invite" data-url="${esc(x.url)}">${t('copy')}</button><button class="secondary" data-action="send-invite" data-url="${esc(x.url)}">${t('sendTelegram')}</button><button class="danger" data-action="revoke-invite" data-token="${esc(x.token)}">${t('revoke')}</button></div></div>`}catch(err){toast(err.message);e.submitter.disabled=false}})}
function settingsModal(){const f=state.folder;openModal(`<h2>${t('settings')}</h2><form id="settingsForm"><div class="field"><label>${t('name')}</label><textarea name="name" maxlength="160" required>${esc(f.name)}</textarea></div><div class="field"><label>${t('source')}</label><select name="source">${languageOptions(f.source_lang)}</select></div><div class="field"><label>${t('target')}</label><select name="target">${languageOptions(f.target_lang)}</select></div><button class="primary" style="width:100%">${t('save')}</button></form><div class="settings-section"><h3>${t('participants')}</h3>${f.members.map(memberRow).join('')}</div><div class="settings-section"><button class="danger" style="width:100%" data-action="delete-folder">${t('deleteFolder')}</button></div>`);document.querySelector('#settingsForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);e.submitter.disabled=true;try{await api(`/api/folders/${f.id}`,{method:'PATCH',body:JSON.stringify({name:fd.get('name'),source_lang:fd.get('source'),target_lang:fd.get('target')})});closeModal();await refreshHome();await renderFolder(f.id);toast(t('saved'))}catch(err){toast(err.message);e.submitter.disabled=false}})}
function memberRow(m){const owner=m.role==='owner';return `<div class="member-row"><div class="member-identity">${avatarMarkup(m.avatar,m.name||String(m.telegram_id),'member-avatar')}<div><b>${esc(m.name||String(m.telegram_id))}</b><div class="hint">${owner?t('owner'):t(m.role)}</div></div></div>${owner?`<span aria-label="${t('owner')}">${icon('user',true)}</span>`:`<div class="member-actions"><select data-member-role="${m.telegram_id}" aria-label="${t('participants')}"><option value="member" ${m.role==='member'?'selected':''}>${t('member')}</option><option value="editor" ${m.role==='editor'?'selected':''}>${t('editor')}</option></select><button class="danger" data-action="remove-member" data-id="${m.telegram_id}" aria-label="${t('remove')}">${icon('trash',true)}</button></div>`}</div>`}

function avatarMenu(){const u=state.data.user,a=u.avatar||{};openModal(`<h2>${t('profile')}</h2><div class="avatar-editor-head">${avatarMarkup(a,u.name,'profile-avatar')}<div><b>${esc(u.name)}</b><p class="hint">${t('photoFormats')}</p></div></div><div class="stack"><label class="primary file-button">${icon('camera',true)}${a.custom?t('changePhoto'):t('uploadPhoto')}<input id="avatarFile" type="file" accept="image/jpeg,image/png,image/webp" hidden></label>${a.custom?`<button class="danger" data-action="delete-avatar">${icon('trash',true)}${t('deletePhoto')}</button>`:''}<button class="secondary" data-action="close-modal">${t('cancel')}</button></div>`)}
function drawCrop(){const c=state.crop;if(!c)return;const canvas=document.querySelector('#cropCanvas');if(!canvas)return;const ctx=canvas.getContext('2d'),size=canvas.width,scale=Math.max(size/c.image.naturalWidth,size/c.image.naturalHeight)*c.zoom,w=c.image.naturalWidth*scale,h=c.image.naturalHeight*scale,x=(size-w)/2+c.x,y=(size-h)/2+c.y;ctx.clearRect(0,0,size,size);ctx.drawImage(c.image,x,y,w,h)}
function cropModal(image){state.crop={image,zoom:1,x:0,y:0,drag:null};openModal(`<h2>${t('cropPhoto')}</h2><div class="crop-wrap"><canvas id="cropCanvas" width="512" height="512"></canvas></div><div class="field"><label>${t('zoom')}</label><input id="cropZoom" type="range" min="1" max="3" step="0.01" value="1"></div><div class="button-row"><button class="secondary" data-action="avatar-menu">${t('cancel')}</button><button class="primary" data-action="save-avatar">${t('save')}</button></div>`);drawCrop();const canvas=document.querySelector('#cropCanvas'),zoom=document.querySelector('#cropZoom');zoom.addEventListener('input',()=>{state.crop.zoom=Number(zoom.value);drawCrop()});canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);state.crop.drag={x:e.clientX,y:e.clientY}});canvas.addEventListener('pointermove',e=>{if(!state.crop?.drag)return;const ratio=canvas.width/canvas.getBoundingClientRect().width;state.crop.x+=(e.clientX-state.crop.drag.x)*ratio;state.crop.y+=(e.clientY-state.crop.drag.y)*ratio;state.crop.drag={x:e.clientX,y:e.clientY};drawCrop()});canvas.addEventListener('pointerup',()=>{if(state.crop)state.crop.drag=null})}
function openAvatarFile(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast(t('photoFormats'));return}if(file.size>10*1024*1024){toast(t('photoFormats'));return}const url=URL.createObjectURL(file),image=new Image();image.onload=()=>{URL.revokeObjectURL(url);cropModal(image)};image.onerror=()=>{URL.revokeObjectURL(url);toast(t('photoFormats'))};image.src=url}
async function saveAvatar(button){const canvas=document.querySelector('#cropCanvas');if(!canvas)return;button.disabled=true;button.textContent=t('saving');const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.9));if(!blob){button.disabled=false;return toast(t('error'))}const body=new FormData();body.append('file',blob,'avatar.webp');try{const result=await api('/api/profile/avatar',{method:'POST',body});state.data.user.avatar=result.avatar;updateHeaderAvatar();closeModal();toast(t('photoSaved'));if(state.view==='profile')await renderProfile()}catch(err){toast(err.message);button.disabled=false;button.textContent=t('save')}}
async function deleteAvatar(){const result=await api('/api/profile/avatar',{method:'DELETE'});state.data.user.avatar=result.avatar;updateHeaderAvatar();closeModal();toast(t('photoDeleted'));if(state.view==='profile')await renderProfile()}

async function renderProfile(){state.view='profile';showNav(true);setActive('profile');content.innerHTML=`<section class="profile-card skeleton" style="height:230px"></section><section class="weekly-card skeleton" style="height:230px"></section>`;const p=await api(`/api/profile?timezone_offset=${timezoneOffset()}`),u=state.data.user,w=p.week,max=Math.max(1,...w.days.map(x=>x.unique_words));u.avatar=p.avatar;updateHeaderAvatar();content.innerHTML=`<section class="profile-card"><div class="profile-avatar-wrap">${avatarMarkup(u.avatar,u.name,'profile-avatar')}<button class="avatar-edit" data-action="avatar-menu" aria-label="${u.avatar?.custom?t('changePhoto'):t('uploadPhoto')}">${icon('camera',true)}</button></div><h1>${esc(u.name)}</h1><div class="profile-stats"><div class="stat"><strong>${p.summary.folders}</strong><span>${t('folders')}</span></div><div class="stat"><strong>${p.summary.words}</strong><span>${t('words')}</span></div><div class="stat"><strong>${p.summary.learned}</strong><span>${t('learnedWords')}</span></div><div class="stat"><strong>${p.summary.sessions}</strong><span>${t('sessions')}</span></div><div class="stat"><strong>${p.summary.game_rounds||0}</strong><span>${t('gameRounds')}</span></div></div></section><section class="weekly-card"><h2>${t('week')}</h2>${w.unique_words?`<div class="profile-stats"><div class="stat"><strong>${w.trainings}</strong><span>${t('sessions')}</span></div><div class="stat"><strong>${w.unique_words}</strong><span>${t('uniqueWords')}</span></div><div class="stat"><strong>${w.first_correct}</strong><span>${t('firstCorrect')}</span></div><div class="stat"><strong>${w.accuracy}%</strong><span>${t('accuracy')}</span></div><div class="stat"><strong>${w.new_learned}</strong><span>${t('newLearned')}</span></div><div class="stat"><strong>${w.active_days}</strong><span>${t('activeDays')}</span></div><div class="stat"><strong>${formatDuration(w.duration_seconds)}</strong><span>${t('studyTime')}</span></div></div>`:`<p class="muted">${t('noActivity')}</p>`}<div class="weekly-chart">${w.days.map((d,i)=>`<div class="bar-wrap ${i===6?'today':''}"><div class="bar" style="height:${Math.max(4,d.unique_words/max*100)}%" title="${d.unique_words}"></div><small>${dayLabel(d.date)}</small></div>`).join('')}</div></section><div class="section-head"><h2>${t('profileSettings')}</h2></div><details><summary>${t('interfaceLanguage')}</summary><div class="language-list" style="margin-top:12px">${Object.keys(I18N).map(c=>`<button class="chip ${c===state.locale?'selected':''}" data-action="set-locale" data-locale="${c}">${LANGUAGE_NAMES[c][c]}</button>`).join('')}</div></details>`}
function dayLabel(date){return new Intl.DateTimeFormat(state.locale,{weekday:'short'}).format(new Date(`${date}T12:00:00`)).replace('.','')}
function formatDuration(sec){const m=Math.round(sec/60);return m?t('minutes',{n:m}):t('seconds',{n:sec||0})}

