document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='typingAnswer'){e.preventDefault();document.querySelector('[data-action="check-answer"]')?.click()}if(e.key==='Enter'&&e.target.id==='folderSearch'){e.preventDefault();document.querySelector('[data-action="run-search"]')?.click()}if(e.key==='Enter'&&e.target.id==='catalogSearch'){e.preventDefault();document.querySelector('[data-action="catalog-search"]')?.click()}});
